public static boolean isPrime(int n) {

    // If the number is less than 2, it is not prime
    if (n < 2) {
        return false;
    }

    // Check if the number is divisible by 2 to n - 1
    for (int i = 2; i <= n / 2; i++) {
        if (n % i == 0) {
            return false;
        }
    }

    // If none of the numbers from 2 to n - 1 divide the number, it is prime
    return true;
}

